// Indirect Reseller Customers Retrieval
// Fetches customers associated with an indirect reseller from Partner Center API

var resellerId = input.get("resellerId");
var accessToken = input.get("accessToken");

if (!resellerId || resellerId.trim() === "") {
    log.error("Reseller ID is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Reseller ID is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else if (!accessToken || accessToken.trim() === "") {
    log.error("Access Token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access Token is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else {
    try {
        // Build the filter JSON
        var filter = json.stringify({
            Field: "IndirectReseller",
            Value: resellerId.trim(),
            Operator: "starts_with"
        });

        var encodedFilter = encodeURIComponent(filter);
        var url = "https://api.partnercenter.microsoft.com/v1/customers?filter=" + encodedFilter;

        log.info("Fetching customers for reseller: " + resellerId);

        var response = http.get(url, {
            "Authorization": "Bearer " + accessToken.trim(),
            "Accept": "application/json"
        });

        output.set("StatusCode", response.statusCode);
        output.set("Body", response.body);

        if (response.statusCode >= 200 && response.statusCode < 300) {
            var data = json.parse(response.body);

            output.set("TotalCount", data.totalCount || 0);

            var customers = data.items || [];
            output.set("Customers", json.stringify(customers));
            output.set("CustomerCount", customers.length);

            // Extract customer details
            var customerList = [];
            for (var i = 0; i < customers.length; i++) {
                var customer = customers[i];
                var company = customer.companyProfile || {};
                customerList.push({
                    id: customer.id || "",
                    tenantId: company.tenantId || "",
                    companyName: company.companyName || "",
                    domain: company.domain || "",
                    relationship: customer.relationshipToPartner || ""
                });
            }
            output.set("CustomerSummary", json.stringify(customerList));

            output.set("HasErrors", false);
            output.set("ErrorMessage", "");

            log.info("Successfully retrieved " + customers.length + " customers for reseller");
            tags.trigger("success");
        } else {
            var errorMsg = "API returned status " + response.statusCode;
            try {
                var errorBody = json.parse(response.body);
                if (errorBody.message) errorMsg = errorBody.message;
                else if (errorBody.error_description) errorMsg = errorBody.error_description;
            } catch (e) {
                if (response.body) errorMsg = response.body.substring(0, 500);
            }

            log.error("Failed to retrieve customers: " + errorMsg);
            output.set("HasErrors", true);
            output.set("ErrorMessage", errorMsg);
            output.set("TotalCount", 0);
            output.set("CustomerCount", 0);
            tags.trigger("error");
        }
    } catch (ex) {
        log.error("Request failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Request failed: " + ex.message);
        output.set("StatusCode", 0);
        output.set("TotalCount", 0);
        output.set("CustomerCount", 0);
        tags.trigger("error");
    }
}
